reader = pypdf.PdfReader("/root/sc100-blank.pdf")

target_names = ["Checkbox50", "Checkbox5cb", "Checkbox60", "Checkbox61", "Checkbox62", "Checkbox63"]

for i, page in enumerate(reader.pages):
    if "/Annots" in page:
        for annot in page["/Annots"]:
            obj = annot.get_object()
            t = obj.get("/T")
            if t:
                for target in target_names:
                    if target in t:
                        print(f"Page {i+1} Found field T: {t}")
