try:
    writer = pypdf.PdfWriter(clone_from="/root/sc100-blank.pdf")
except TypeError:
    # Fallback for older pypdf versions if clone_from is not available
    reader = pypdf.PdfReader("/root/sc100-blank.pdf")
    writer = pypdf.PdfWriter()
    writer.append_pages_from_reader(reader)
    # Manually copy AcroForm if it exists
    if "/AcroForm" in reader.trailer["/Root"]:
        writer.root_object.update({
            pypdf.generic.NameObject("/AcroForm"): reader.trailer["/Root"]["/AcroForm"]
